def sliding_median(nums: list[int], k: int) -> list[float]:
    if k <= 0:
        raise ValueError("k must be positive")
    if k > len(nums):
        return []

    result = []
    n = len(nums)

    for i in range(n - k + 1):
        window = nums[i : i + k]
        window.sort()
        mid = k // 2
        if k % 2 == 0:
            median = (window[mid - 1] + window[mid]) / 2.0
        else:
            median = float(window[mid])
        result.append(median)

    return result
