def compare_versions(a: str, b: str) -> int:
 def parse_version(s: str):
 # remove optional prefix 'v' or 'V'
 if s.startswith('v') or s.startswith('V'):
 s = s[1:]
 # split body and pre-release tag
 if '-' in s:
 body, pre = s.split('-', 1)
 pre = pre # keep as string
 else:
 body = s
 pre = None
 # parse body segments into integers
 parts = [int(part) for part in body.split('.')]
 return parts, pre

 parts_a, pre_a = parse_version(a)
 parts_b, pre_b = parse_version(b)

 # compare body parts
 max_len = max(len(parts_a), len(parts_b))
 for i in range(max_len):
 val_a = parts_a[i] if i < len(parts_a) else 0
 val_b = parts_b[i] if i < len(parts_b) else 0
 if val_a != val_b:
 return 1 if val_a > val_b else -1

 # compare pre-release tags
 if pre_a is None and pre_b is None:
 return 0
 if pre_a is None:
 return 1 # a has no tag, so a > b
 if pre_b is None:
 return -1 # b has no tag, so b > a
 # both have tags, compare lexicographically
 if pre_a < pre_b:
 return -1
 elif pre_a > pre_b:
 return 1
 else:
